type Handler struct {
    mu sync.RWMutex; views map[ViewID]View; factory map[string]func(*Model) View
}
func (h *Handler) Open(kind string, m *Model) ViewID {
    h.mu.Lock(); defer h.mu.Unlock()
    h.next++; h.views[ViewID(h.next)] = h.factory[kind](m)  // create + register
    return ViewID(h.next)                                   // handle, not the view
}
func (h *Handler) Notify(m *Model) {
    h.mu.RLock(); snap := make([]View, 0, len(h.views))
    for _, v := range h.views { snap = append(snap, v) }
    h.mu.RUnlock()                        // release before calling into views:
    for _, v := range snap { v.Update(m) }   // a view may Open/Close re-entrantly
}
